(()=>{
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mapCanvas=document.getElementById('map'),mctx=mapCanvas.getContext('2d');
const $=s=>document.querySelector(s), W=1600,H=1200, TAU=Math.PI*2;
let vw=innerWidth,vh=innerHeight,dpr=Math.min(devicePixelRatio||1,2),last=0,now=0,toastTimer=0,mouse={x:vw/2,y:vh/2},keys={},paused=true,dialogOpen=false;
const zones=[
 {name:'Тихая заводь',sub:'Внутреннее кольцо',ground:'#30382e',accent:'#76815b',type:'village',gate:'Равнины Пепельного Ветра',desc:'Пепельная деревня под защитой старых стен.'},
 {name:'Равнины Пепельного Ветра',sub:'Второе кольцо',ground:'#656347',accent:'#aaa16b',type:'plain',gate:'Сумрачный лес',desc:'Слизни, кабаны и древнее логово.'},
 {name:'Сумрачный лес',sub:'Третье кольцо',ground:'#34483b',accent:'#668267',type:'forest',gate:'Чаща Безлунья',desc:'Крипты, звери и спящий Энт.'},
 {name:'Чаща Безлунья',sub:'Четвёртое кольцо',ground:'#242e2b',accent:'#637054',type:'dark',gate:'Ветряные пики',desc:'Эльфийские тропы и корень скверны.'},
 {name:'Ветряные пики',sub:'Пятое кольцо',ground:'#535a5c',accent:'#a5a9a0',type:'mountain',gate:'Край Пепла',desc:'Каменные великаны и крылатые тени.'}
];
const rarity=['Обычное','Необычное','Редкое','Эпическое','Легендарное','Мифическое'];
const weapons=[
 {name:'Ржавый клинок',type:'melee',rarity:0,dmg:17,desc:'Старый меч дозорной.'},
 {name:'Дубовый лук',type:'ranged',rarity:1,dmg:13,desc:'Дальняя атака стрелой.'},
 {name:'Искра праха',type:'magic',rarity:2,dmg:22,desc:'Сгусток сумрачного пламени.'},
 {name:'Секира Рогатого',type:'melee',rarity:3,dmg:32,desc:'Тяжёлое оружие с костяным навершием.'},
 {name:'Лук полой луны',type:'ranged',rarity:4,dmg:29,desc:'Пробивает врагов насквозь.'},
 {name:'Меч героя',type:'melee',rarity:5,dmg:58,desc:'Меч, выкованный в сердце камня.'}
];
const skins=[{name:'Тёмный рыцарь',ref:'отсылка к легенде о падшем защитнике',unlocked:false},{name:'Назгулова тень',ref:'отсылка к всадникам тьмы',unlocked:false},{name:'Ситх: красная пустота',ref:'отсылка к звёздной саге',unlocked:false}];
const player={x:800,y:650,r:15,hp:100,maxHp:100,level:1,xp:0,next:100,dmg:0,speed:210,weapon:0,coins:12,attackCd:0,magicCd:0,invuln:0,dash:0,face:0};
let zone=0,day=1,selectedSkin=-1,inventory=[weapons[0]],enemies=[],projectiles=[],particles=[],decor=[],bossDead=[false,false,false,false,false],quest={stage:0,kills:0,crypt:false,glyphs:0,elfClue:0,roots:false,items:0},journalLog=['Пять колец связаны с древним Пепельным Кругом. Дозорная Мира ждёт у колодца.'];
const npcSet=[
 [{name:'Мира, дозорная',x:730,y:590,kind:'mira'},{name:'Бран, кузнец',x:1010,y:690,kind:'smith'},{name:'Старый Отто',x:590,y:820,kind:'elder'}],
 [{name:'Следопыт Рун',x:760,y:820,kind:'rune'},{name:'Костяной указатель',x:1300,y:450,kind:'glyph'}],
 [{name:'Хранительница крипты',x:290,y:880,kind:'crypt'},{name:'Энт Старокорень',x:1250,y:280,kind:'boss3'},{name:'Камень-память',x:1050,y:800,kind:'glyph'}],
 [{name:'Эльфийка Лиан',x:360,y:620,kind:'elf'},{name:'Слепой оракул',x:1180,y:900,kind:'oracle'},{name:'Сквернокорень',x:1250,y:280,kind:'boss4'},{name:'Чёрный обелиск',x:780,y:340,kind:'glyph'}],
 [{name:'Страж пиков',x:800,y:930,kind:'peak'},{name:'Сердце горы',x:800,y:255,kind:'boss5'}]
];
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);mapCanvas.width=220*dpr;mapCanvas.height=166*dpr;mctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function npcPosition(n){return {x:n.x,y:n.y}}
function makeEnemy(type,x,y,boss=false){const data={slime:['Слизень',32,7,30,'#91a970'],boar:['Клыкач',75,14,55,'#986d49'],wolf:['Сумрачный волк',58,12,43,'#828b7d'],fox:['Пепельная лиса',38,9,38,'#b67e50'],bear:['Лесной медведь',125,19,80,'#695342'],skeleton:['Заблудший скелет',62,13,48,'#c4b998'],draugr:['Драугр',96,17,75,'#879c91'],elf:['Эльф-разбойник',72,16,65,'#8e766f'],sprite:['Лесной дух',54,12,60,'#82b5a2'],golem:['Осколочный голем',110,19,85,'#9b9e91'],wyvern:['Пепельная виверна',90,17,95,'#ad7666'],bossboar:['Матёрый Клыкач',330,21,260,'#996247'],ent:['Старокорень, Энт',470,24,420,'#77854a'],root:['Корень Бездны',610,27,600,'#7c4768'],golemBoss:['Сердцегранит',820,32,1100,'#a9a99b']}[type];
return {type,name:data[0],x,y,hp:data[1],maxHp:data[1],dmg:data[2],xp:data[3],color:data[4],boss,r:boss?38:17,attackCd:Math.random(),hit:0,phase:0,dead:false};}
function spawnZone(){enemies=[];projectiles=[];decor=[];const add=(t,x,y)=>enemies.push(makeEnemy(t,x,y));
if(zone===0){for(let i=0;i<24;i++)decor.push({type:Math.random()<.54?'house':'tree',x:160+Math.random()*1280,y:130+Math.random()*940,scale:.7+Math.random()*.7})}
if(zone===1){for(let i=0;i<13;i++)add(i<8?'slime':'boar',150+Math.random()*1300,140+Math.random()*920);decor=makeDecor('grass',55)}
if(zone===2){for(let i=0;i<14;i++)add(['wolf','fox','skeleton','draugr','bear'][i%5],120+Math.random()*1360,100+Math.random()*1000);decor=makeDecor('tree',68);decor.push({type:'crypt',x:300,y:900,scale:1})}
if(zone===3){for(let i=0;i<14;i++)add(i<6?'sprite':i<10?'elf':'wolf',130+Math.random()*1350,120+Math.random()*960);decor=makeDecor('darktree',74);for(let i=0;i<6;i++)decor.push({type:'elfhouse',x:190+i%3*110,y:290+Math.floor(i/3)*110,scale:.8})}
if(zone===4){for(let i=0;i<12;i++)add(i<8?'golem':'wyvern',110+Math.random()*1380,110+Math.random()*980);decor=makeDecor('rock',56)}
const bosses=['bossboar','ent','root','golemBoss'];const bossZone=zone-1;if(bossZone>=0&&bossZone<4&&!bossDead[bossZone]){let pos=[{x:1340,y:890},{x:1250,y:280},{x:1250,y:280},{x:800,y:255}][bossZone];enemies.push(makeEnemy(bosses[bossZone],pos.x,pos.y,true))}
}
function makeDecor(type,n){let out=[];for(let i=0;i<n;i++)out.push({type,x:50+Math.random()*1500,y:60+Math.random()*1080,scale:.55+Math.random()*1.25,seed:Math.random()});return out}
function enterZone(z){zone=Math.max(0,Math.min(4,z));player.x=zone===0?800:95;player.y=zone===0?650:600;spawnZone();$('#location').textContent=zones[zone].name+' · '+zones[zone].sub;toast('Вы вошли: '+zones[zone].name);journalLog.push('Открыта область: '+zones[zone].name+'.');updateHud()}
function weapon(){return weapons[player.weapon]||weapons[0]}
function addXP(n){player.xp+=n;while(player.xp>=player.next){player.xp-=player.next;player.level++;player.next=Math.floor(player.next*1.38);player.maxHp+=12;player.hp=player.maxHp;player.dmg+=3;toast('Уровень повышен: '+player.level+' · здоровье восстановлено');}updateHud()}
function updateHud(){const pct=100*player.hp/player.maxHp;$('#hpBar').style.width=Math.max(0,pct)+'%';$('#hpText').textContent=Math.ceil(player.hp)+' / '+player.maxHp;$('#xpBar').style.width=(player.xp/player.next*100)+'%';$('#xpText').textContent=player.xp+' / '+player.next+' XP';$('#level').textContent=player.level;$('#weaponName').innerHTML=weapon().name+'<small>'+rarity[weapon().rarity]+' · '+({melee:'ближний бой',ranged:'дальний бой',magic:'магия'}[weapon().type])+'</small>';const qs=[['Пепел у порога','Поговорите с дозорной Мирой у старого колодца.','◉ Найдите Миру в деревне'],['Клыки на ветру','Уничтожьте слизней и кабанов на равнинах.','◉ Побеждено: '+quest.kills+' / 5'],['Берлога Клыкача','Победите хозяина равнин в его берлоге.','◉ Найдите логово на востоке равнин'],['Кости помнят','Отыщите крипту и добудьте костяную печать.','◉ Исследуйте крипту в Сумрачном лесу'],['Пробуждение Старокорня','Победите Энта у старого дерева.','◉ Босс повержен: '+(bossDead[1]?'да':'нет')],['Шёпот безлунья','Соберите три знака и узнайте правду у эльфов.','◉ Знаки: '+quest.glyphs+' / 3 · эльфийская подсказка: '+quest.elfClue+'/1'],['Корень скверны','Остановите существо из корней.','◉ Сквернокорень: '+(bossDead[2]?'побеждён':'жив')],['Путь к сердцу','Добудьте три осколка у големов и найдите Стража пиков.','◉ Осколки: '+quest.items+' / 3'],['Меч героя','Одолейте Сердцегранита и заберите меч из его сердца.','◉ Финальный босс: '+(bossDead[3]?'побеждён':'жив')],['Хранитель колец','Пять колец спасены. Но тени ещё хранят секреты.','◉ Путь завершён']];let q=qs[Math.min(quest.stage,9)];$('#questTitle').textContent=q[0];$('#questText').textContent=q[1];$('#objective').textContent=q[2]}

