function camera(){return {x:Math.max(0,Math.min(W-vw,player.x-vw/2)),y:Math.max(0,Math.min(H-vh,player.y-vh/2))}}
function worldPaint(){let c=camera(),z=zones[zone];ctx.fillStyle=z.ground;ctx.fillRect(0,0,vw,vh);ctx.save();ctx.translate(-c.x,-c.y);
// painterly mottled ground
for(let i=0;i<130;i++){let x=(i*173+31)%W,y=(i*293+91)%H;ctx.globalAlpha=.08;ctx.fillStyle=i%3?z.accent:'#d5c795';ctx.beginPath();ctx.ellipse(x,y,35+(i%7)*7,18+(i%5)*5,(i%9)*.3,0,TAU);ctx.fill()}ctx.globalAlpha=1;
if(zone===0)drawVillage();if(zone===1)drawPlains();if(zone===2)drawForest();if(zone===3)drawDark();if(zone===4)drawPeaks();
decor.forEach(drawDecor);drawGates();drawNPCs();enemies.forEach(drawEnemy);projectiles.forEach(drawProjectile);particles.forEach(drawParticle);drawPlayer();ctx.restore();drawMap(c);drawInteraction(c)}
function drawVillage(){ctx.fillStyle='#50483b';ctx.beginPath();ctx.ellipse(800,650,290,210,-.15,0,TAU);ctx.fill();ctx.strokeStyle='#837456';ctx.lineWidth=28;ctx.beginPath();ctx.ellipse(800,650,465,360,0,0,TAU);ctx.stroke();ctx.strokeStyle='#927f59';ctx.lineWidth=2;for(let i=0;i<18;i++){let a=i*TAU/18;ctx.beginPath();ctx.moveTo(800+465*Math.cos(a),650+360*Math.sin(a));ctx.lineTo(800+482*Math.cos(a),650+377*Math.sin(a));ctx.stroke()}ctx.fillStyle='#77745c';ctx.beginPath();ctx.ellipse(795,630,29,18,0,0,TAU);ctx.fill();ctx.fillStyle='#171d19';ctx.beginPath();ctx.ellipse(795,630,19,10,0,0,TAU);ctx.fill();ctx.fillStyle='#d5bc7b';ctx.font='13px sans-serif';ctx.fillText('Колодец',815,624)}
function drawPlains(){ctx.fillStyle='#7a7454';ctx.beginPath();ctx.ellipse(1340,890,90,56,-.1,0,TAU);ctx.fill();ctx.fillStyle='#24281e';ctx.beginPath();ctx.ellipse(1340,890,57,31,0,0,TAU);ctx.fill();ctx.fillStyle='#d8c694';ctx.font='14px sans-serif';ctx.fillText('Берлога',1302,965)}
function drawForest(){ctx.fillStyle='#272e25';ctx.beginPath();ctx.ellipse(300,900,90,60,0,0,TAU);ctx.fill();ctx.fillStyle='#a7a48a';ctx.font='13px sans-serif';ctx.fillText('Склеп',267,976)}
function drawDark(){ctx.globalAlpha=.15;ctx.fillStyle='#9c5071';ctx.beginPath();ctx.arc(800,600,300,0,TAU);ctx.fill();ctx.globalAlpha=1}
function drawPeaks(){ctx.fillStyle='#747a79';for(let i=0;i<8;i++){let x=160+i*190;ctx.beginPath();ctx.moveTo(x,320+Math.sin(i)*80);ctx.lineTo(x+140,40+Math.sin(i)*40);ctx.lineTo(x+300,350);ctx.closePath();ctx.fill()}ctx.fillStyle='#d5d6cd';ctx.font='13px sans-serif';ctx.fillText('Сердце горы',750,160)}
function drawDecor(d){let {x,y,scale:s,type}=d;ctx.save();ctx.translate(x,y);if(type==='tree'||type==='darktree'){let dark=type==='darktree';ctx.fillStyle=dark?'#121b19':'#25382b';ctx.beginPath();ctx.ellipse(3,10,18*s,10*s,0,0,TAU);ctx.fill();ctx.fillStyle=dark?'#3b4838':'#536b48';ctx.beginPath();ctx.arc(0,-5,18*s,0,TAU);ctx.fill();ctx.beginPath();ctx.arc(-9*s,-13*s,12*s,0,TAU);ctx.fill();ctx.beginPath();ctx.arc(10*s,-14*s,13*s,0,TAU);ctx.fill();ctx.fillStyle='#4b4332';ctx.fillRect(-3*s,4*s,6*s,16*s)}else if(type==='house'||type==='elfhouse'){ctx.fillStyle=type==='house'?'#51493b':'#303b34';ctx.fillRect(-21*s,-8*s,42*s,30*s);ctx.fillStyle=type==='house'?'#493327':'#394739';ctx.beginPath();ctx.moveTo(-26*s,-8*s);ctx.lineTo(0,-29*s);ctx.lineTo(26*s,-8*s);ctx.closePath();ctx.fill();ctx.fillStyle='#d6ac68';ctx.fillRect(7*s,1*s,7*s,9*s);if(type==='house'){ctx.fillStyle='#605944';ctx.fillRect(-10*s,0,7*s,6*s)}}else if(type==='rock'||type==='crypt'){ctx.fillStyle=type==='crypt'?'#706d60':'#777c7a';ctx.beginPath();ctx.moveTo(-20*s,12*s);ctx.lineTo(-16*s,-12*s);ctx.lineTo(-5*s,-21*s);ctx.lineTo(13*s,-15*s);ctx.lineTo(21*s,8*s);ctx.closePath();ctx.fill();if(type==='crypt'){ctx.fillStyle='#171b18';ctx.fillRect(-11*s,-2*s,22*s,18*s);ctx.fillStyle='#b8aa81';ctx.fillRect(-14*s,-8*s,28*s,5*s)}}else{ctx.strokeStyle='#9b9863';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-6+i*7,12);ctx.lineTo(-10+i*9,-3);ctx.lineTo(-4+i*8,-14);ctx.stroke()}}ctx.restore()}

