function gate(x,y,mark,label){ctx.save();ctx.translate(x,y);ctx.strokeStyle='#c8ad7066';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,30,42,0,0,TAU);ctx.stroke();ctx.fillStyle='#cdb879';ctx.font='20px serif';ctx.textAlign='center';ctx.fillText(mark,0,7);ctx.fillStyle='#d0c49f';ctx.font='11px sans-serif';ctx.fillText(label,0,58);ctx.restore()}
