function drawInteraction(c){let near=null,best=72;for(const n of npcSet[zone]){let d=Math.hypot(n.x-player.x,n.y-player.y);if(d<best){best=d;near=n}}let gateNear=false;if(zone===0)gateNear=Math.hypot(player.x-800,player.y-155)<70;else gateNear=player.x<120||player.x>1480;if(near)$('#interaction').textContent='[ E ] поговорить · '+near.name;else if(gateNear)$('#interaction').textContent='[ E ] перейти в другое кольцо';else $('#interaction').textContent=''}

