function openPanel(html){$('#panelContent').innerHTML=html;$('#panel').classList.add('open');dialogOpen=true}
function closePanel(){$('#panel').classList.remove('open');dialogOpen=false}
function actionButton(label,fn){return `<button class="action" data-act="${fn}">${label}</button>`}
function speak(n){let title=n.name,text='',buttons='';if(n.kind==='mira'){if(quest.stage===0){text='«Ты проснулась вовремя. На равнинах у старой берлоги шевелится что-то огромное. Возьми мой лук — и не доверяй огням в лесу. Пять тварей на равнинах должны пасть, прежде чем Клыкач выйдет из логова».';buttons=actionButton('Принять поручение · получить лук','acceptMira')}else{text='«Кольца не просто границы — это замок. Корни его уже грызут. Иди дальше, пока тьма не нашла дорогу сюда».';buttons=actionButton('Пожертвовать 3 осколка праха · исцелиться','heal')}}
if(n.kind==='smith'){text='«Сталь помнит руку, что её держала. У меня найдётся оружие получше, если принесёшь трофеи».';buttons=actionButton('Купить Искру праха · 18 монет','buyMagic')+actionButton('Купить Секиру Рогатого · 35 монет','buyAxe')}
if(n.kind==='elder'){text='«Старые истории говорят о трёх чёрных именах. Назови их верно — и тень ляжет на клинок. Ключ к первому имени лежит там, где мёртвые не спят».';buttons=actionButton('Узнать про цепочку скинов','skinLore')}
