document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(b)handleAction(b.dataset.act)});
function textLog(s){journalLog.push(s);openPanel(`<div class="eyebrow">Запись в журнале</div><h2>Старое предание</h2><p>${s}</p>`)}
function openInventory(){let html='<div class="eyebrow">Снаряжение и добыча</div><h2>Сумка путника</h2><p>Монеты: '+player.coins+' · Уровень: '+player.level+'</p><div class="eyebrow" style="margin-top:17px">Оружие · нажмите чтобы экипировать</div>';inventory.forEach(w=>{html+=`<div class="item"><span>${w.name}<small>${rarity[w.rarity]} · ${w.desc} · ${w.dmg+player.dmg} урона</small></span><button class="action" data-act="equip:${weapons.indexOf(w)}">${weapon()===w?'В руках':'Экипировать'}</button></div>`});let eligible=weapon().rarity>=5||inventory.some(w=>w.rarity>=5);html+='<div class="eyebrow" style="margin-top:18px">Тёмные облики</div>';skins.forEach((s,i)=>html+=`<div class="item"><span class="${s.unlocked?'rarity':''}">${s.name}<small>${s.unlocked?s.ref:'Заперто · запутанная цепочка в Сумрачном лесу'}</small></span>${s.unlocked&&eligible?`<button class="action" data-act="skin:${i}">${selectedSkin===i?'Выбран':'Применить'}</button>`:`<span>${s.unlocked?'Требуется мифическое оружие':'🔒'}</span>`}</div>`);html+='<p style="font-size:10px">Скины применяются только к мифическому оружию и выше.</p>';openPanel(html)}
function journal(){let html='<div class="eyebrow">Путь сквозь пять колец</div><h2>Журнал странника</h2><div class="journalEntry"><b>'+$('#questTitle').textContent+'</b><br>'+$('#questText').textContent+'<br><small>'+$('#objective').textContent+'</small></div>';journalLog.slice().reverse().forEach(x=>html+=`<div class="journalEntry">${x}</div>`);html+='<div class="eyebrow" style="margin-top:17px">Снаряжение · шесть редкостей</div><p>Обычное · Необычное · Редкое · Эпическое · Легендарное · Мифическое</p>';openPanel(html)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(!b)return;let a=b.dataset.act;if(a.startsWith('equip:')){let i=Number(a.split(':')[1]);player.weapon=i;toast('Экипировано: '+weapon().name);updateHud();openInventory()}else if(a.startsWith('skin:')){let i=Number(a.split(':')[1]);if(weapon().rarity<5){toast('Для скина нужно мифическое оружие');return}selectedSkin=i;toast('Облик применён: '+skins[i].name);openInventory()}else handleAction(a)});

