let touchDir=null,touchOrigin=null;
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e')interact();if(k==='q')magic();if(k==='j'){dialogOpen?closePanel():journal()}if(k==='i'){dialogOpen?closePanel():openInventory()}if(k==='escape')closePanel();if(k==='1'||k==='2'||k==='3'){let i=Number(k)-1;if(inventory[i]){player.weapon=weapons.indexOf(inventory[i]);updateHud()}}if(k==='shift')player.dash=.25});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
