const joy=$('#joystick'),stick=$('#stick');joy.addEventListener('touchstart',e=>{e.preventDefault();touchOrigin={x:e.touches[0].clientX,y:e.touches[0].clientY};joy.setPointerCapture?.(e.pointerId)});joy.addEventListener('touchmove',e=>{e.preventDefault();if(!touchOrigin)return;let t=e.touches[0],x=t.clientX-touchOrigin.x,y=t.clientY-touchOrigin.y,l=Math.hypot(x,y),m=Math.min(l,34);touchDir=l?{x:x/l*m/34,y:y/l*m/34}:{x:0,y:0};stick.style.transform=`translate(${touchDir.x*34}px,${touchDir.y*34}px)`},{passive:false});function endJoy(){touchOrigin=null;touchDir=null;stick.style.transform=''}joy.addEventListener('touchend',endJoy);joy.addEventListener('touchcancel',endJoy);
